  "CREATE TRIGGER IF NOT EXISTS publication_contribution_insert AFTER INSERT ON document_publication_contributions BEGIN\n\n      INSERT INTO document_publication_totals(project_id,session_id,kind,generation,bytes,pending,sources,imported)\n    SELECT NEW.project_id,NEW.session_id,NEW.kind,NEW.generation,1*NEW.bytes,1*NEW.pending,1*NEW.sources,1*NEW.imported WHERE (1) AND (NEW.bytes<>0 OR NEW.pending<>0 OR NEW.sources<>0 OR NEW.imported<>0)\n      AND (NEW.kind='source' OR NEW.generation>=COALESCE((SELECT generation FROM session_documents WHERE (project_id,session_id)=(NEW.project_id,NEW.session_id)),0))\n    ON CONFLICT(project_id,session_id,kind,generation) DO UPDATE SET bytes=bytes+excluded.bytes,pending=pending+excluded.pending,sources=sources+excluded.sources,imported=imported+excluded.imported;\n      DELETE FROM document_publication_totals\n        WHERE (project_id,session_id,kind,generation)=(NEW.project_id,NEW.session_id,NEW.kind,NEW.generation)\n          AND ((sources=0 AND bytes=0 AND pending=0 AND imported=0) OR (kind='frontier' AND EXISTS(SELECT 1 FROM session_documents\n            WHERE (project_id,session_id)=(NEW.project_id,NEW.session_id) AND generation>NEW.generation))); END",
  "DROP TRIGGER IF EXISTS transcripts_facts_insert",
  "CREATE TRIGGER IF NOT EXISTS transcripts_facts_insert AFTER INSERT ON transcripts\n         BEGIN\n        DELETE FROM document_publication_contributions WHERE (project_id,transcript_id) IN (SELECT NEW.project_id AS project_id,NEW.transcript_id AS transcript_id)\nAND NOT EXISTS (SELECT 1 FROM (SELECT t.project_id,t.transcript_id,'source' AS kind,0 AS generation,t.session_id,\nt.size AS bytes,(t.size>0) AS pending,1 AS sources,(t.imported_at IS NOT NULL) AS imported\nFROM (SELECT NEW.project_id AS project_id,NEW.transcript_id AS transcript_id) k CROSS JOIN transcripts t ON (t.project_id,t.transcript_id)=(k.project_id,k.transcript_id)\nUNION ALL\nSELECT t.project_id,t.transcript_id,'frontier',p.generation,t.session_id,\n-MIN(t.size,p.published_offset),-(t.size>0 AND p.published_offset>=t.size),0,0\nFROM (SELECT NEW.project_id AS project_id,NEW.transcript_id AS transcript_id) k CROSS JOIN transcripts t ON (t.project_id,t.transcript_id)=(k.project_id,k.transcript_id)\nLEFT JOIN session_documents d ON (d.project_id,d.session_id)=(t.project_id,t.session_id)\nCROSS JOIN transcript_publication p ON (p.project_id,p.transcript_id)=(t.project_id,t.transcript_id) AND p.generation>=COALESCE(d.generation,0)) s WHERE\n(s.project_id,s.transcript_id,s.kind,s.generation)=(document_publication_contributions.project_id,\ndocument_publication_contributions.transcript_id,document_publication_contributions.kind,document_publication_contributions.generation));INSERT INTO document_publication_contributions(project_id,transcript_id,kind,generation,session_id,bytes,pending,sources,imported) SELECT project_id,transcript_id,kind,generation,session_id,bytes,pending,sources,imported FROM (SELECT t.project_id,t.transcript_id,'source' AS kind,0 AS generation,t.session_id,\nt.size AS bytes,(t.size>0) AS pending,1 AS sources,(t.imported_at IS NOT NULL) AS imported\nFROM (SELECT NEW.project_id AS project_id,NEW.transcript_id AS transcript_id) k CROSS JOIN transcripts t ON (t.project_id,t.transcript_id)=(k.project_id,k.transcript_id)\nUNION ALL\nSELECT t.project_id,t.transcript_id,'frontier',p.generation,t.session_id,\n-MIN(t.size,p.published_offset),-(t.size>0 AND p.published_offset>=t.size),0,0\nFROM (SELECT NEW.project_id AS project_id,NEW.transcript_id AS transcript_id) k CROSS JOIN transcripts t ON (t.project_id,t.transcript_id)=(k.project_id,k.transcript_id)\nLEFT JOIN session_documents d ON (d.project_id,d.session_id)=(t.project_id,t.session_id)\nCROSS JOIN transcript_publication p ON (p.project_id,p.transcript_id)=(t.project_id,t.transcript_id) AND p.generation>=COALESCE(d.generation,0)) WHERE true\nON CONFLICT(project_id,transcript_id,kind,generation) DO UPDATE SET\nsession_id=excluded.session_id,bytes=excluded.bytes,pending=excluded.pending,sources=excluded.sources,imported=excluded.imported\nWHERE (document_publication_contributions.session_id,document_publication_contributions.bytes,document_publication_contributions.pending,document_publication_contributions.sources,document_publication_contributions.imported)\nIS NOT (excluded.session_id,excluded.bytes,excluded.pending,excluded.sources,excluded.imported);\n        DELETE FROM document_publication_facts WHERE (project_id,session_id) IN (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id)\nAND NOT EXISTS (SELECT 1 FROM session_documents d WHERE (d.project_id,d.session_id)=(document_publication_facts.project_id,document_publication_facts.session_id));INSERT INTO document_publication_facts(project_id,session_id,state,due_at,transcripts,bytes,imported,classes)\nSELECT d.project_id,d.session_id,d.state,d.due_at,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.transcripts,0) WHEN d.state='live' THEN COALESCE(s.pending,0)+COALESCE(f.pending,0) ELSE 0 END,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.bytes,0) WHEN d.state='live' THEN COALESCE(s.bytes,0)+COALESCE(f.bytes,0) ELSE 0 END,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.imported,0) ELSE COALESCE(s.sources,0)>0 AND s.imported=s.sources END,\nCASE WHEN d.state='live' AND json_valid(d.build) THEN COALESCE(json_extract(d.build,'$.report.classes'),'{}') ELSE '{}' END\nFROM (SELECT NEW.project_id AS project_id,NEW.session_id AS session_id) k CROSS JOIN session_documents d ON (d.project_id,d.session_id)=(k.project_id,k.session_id)\nLEFT JOIN document_publication_totals s ON (s.project_id,s.session_id,s.kind,s.generation)=(d.project_id,d.session_id,'source',0)\nLEFT JOIN document_publication_totals f ON (f.project_id,f.session_id,f.kind,f.generation)=(d.project_id,d.session_id,'frontier',d.generation)\nLEFT JOIN document_publication_ready r ON (r.project_id,r.session_id)=(d.project_id,d.session_id)\nLEFT JOIN document_publication_facts held ON (held.project_id,held.session_id)=(d.project_id,d.session_id)\nWHERE true\nON CONFLICT(project_id,session_id) DO UPDATE SET\nstate=excluded.state,due_at=excluded.due_at,transcripts=excluded.transcripts,bytes=excluded.bytes,imported=excluded.imported,classes=excluded.classes\nWHERE (document_publication_facts.state,document_publication_facts.due_at,document_publication_facts.transcripts,document_publication_facts.bytes,document_publication_facts.imported,document_publication_facts.classes)\nIS NOT (excluded.state,excluded.due_at,excluded.transcripts,excluded.bytes,excluded.imported,excluded.classes); END",
