  "CREATE TRIGGER IF NOT EXISTS session_documents_facts_delete AFTER DELETE ON session_documents\n       BEGIN DELETE FROM document_publication_facts WHERE (project_id,session_id) IN (SELECT OLD.project_id AS project_id,OLD.session_id AS session_id)\nAND NOT EXISTS (SELECT 1 FROM session_documents d WHERE (d.project_id,d.session_id)=(document_publication_facts.project_id,document_publication_facts.session_id));INSERT INTO document_publication_facts(project_id,session_id,state,due_at,transcripts,bytes,imported,classes)\nSELECT d.project_id,d.session_id,d.state,d.due_at,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.transcripts,0) WHEN d.state='live' THEN COALESCE(s.pending,0)+COALESCE(f.pending,0) ELSE 0 END,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.bytes,0) WHEN d.state='live' THEN COALESCE(s.bytes,0)+COALESCE(f.bytes,0) ELSE 0 END,\nCASE WHEN r.session_id IS NULL THEN COALESCE(held.imported,0) ELSE COALESCE(s.sources,0)>0 AND s.imported=s.sources END,\nCASE WHEN d.state='live' AND json_valid(d.build) THEN COALESCE(json_extract(d.build,'$.report.classes'),'{}') ELSE '{}' END\nFROM (SELECT OLD.project_id AS project_id,OLD.session_id AS session_id) k CROSS JOIN session_documents d ON (d.project_id,d.session_id)=(k.project_id,k.session_id)\nLEFT JOIN document_publication_totals s ON (s.project_id,s.session_id,s.kind,s.generation)=(d.project_id,d.session_id,'source',0)\nLEFT JOIN document_publication_totals f ON (f.project_id,f.session_id,f.kind,f.generation)=(d.project_id,d.session_id,'frontier',d.generation)\nLEFT JOIN document_publication_ready r ON (r.project_id,r.session_id)=(d.project_id,d.session_id)\nLEFT JOIN document_publication_facts held ON (held.project_id,held.session_id)=(d.project_id,d.session_id)\nWHERE true\nON CONFLICT(project_id,session_id) DO UPDATE SET\nstate=excluded.state,due_at=excluded.due_at,transcripts=excluded.transcripts,bytes=excluded.bytes,imported=excluded.imported,classes=excluded.classes\nWHERE (document_publication_facts.state,document_publication_facts.due_at,document_publication_facts.transcripts,document_publication_facts.bytes,document_publication_facts.imported,document_publication_facts.classes)\nIS NOT (excluded.state,excluded.due_at,excluded.transcripts,excluded.bytes,excluded.imported,excluded.classes); END",
